export function Script_ShowLinkTrainerCard(): any {
  ShowTrainerCardInLink(gSpecialVar_0x8006, CB2_ReturnToFieldContinueScriptPlayMapMusic);
}

/** bool32 GetLinkTrainerCardColor(u8 linkPlayerIndex) */
export function GetLinkTrainerCardColor(linkPlayerIndex: any): any {
  let numStars: any = null;

      gSpecialVar_0x8006 = linkPlayerIndex;
      StringCopy(gStringVar1, gLinkPlayers[linkPlayerIndex].name);

      numStars = GetTrainerCardStars(linkPlayerIndex);
      if (numStars == 0)
          return FALSE;

      StringCopy(gStringVar2, sTrainerCardColorNames[numStars - 1]);
      return TRUE;
}

/** void Task_WaitForLinkPlayerConnection(u8 taskId) */
export function Task_WaitForLinkPlayerConnection(taskId: any): any {
  let task: any =gTasks[taskId];

      task.tTimer++;
      if (task.tTimer > 480)  
      {
          CloseLink();
          SetMainCallback2(CB2_LinkError);
          DestroyTask(taskId);
      }

      if (gReceivedRemoteLinkPlayers)
      {
           
          if (gWirelessCommType == 0)
          {
              if (!DoesLinkPlayerCountMatchSaved())
              {
                  CloseLink();
                  SetMainCallback2(CB2_LinkError);
              }
              DestroyTask(taskId);
          }
          else
          {
              DestroyTask(taskId);
          }
      }
}

/** static void Task_WaitExitToScript(u8 taskId) */
export function Task_WaitExitToScript(taskId: any): any {
  if (!gReceivedRemoteLinkPlayers)
      {
          ScriptContext_Enable();
          DestroyTask(taskId);
      }
}

/** void Task_ReconnectWithLinkPlayers(u8 taskId) */
export function Task_ReconnectWithLinkPlayers(taskId: any): any {
  let data: any = gTasks[taskId].data;

      switch (tState)
      {
      case 0:
          if (gWirelessCommType != 0)
          {
              DestroyTask(taskId);
          }
          else
          {
              OpenLink();
              CreateTask(Task_WaitForLinkPlayerConnection, 1);
              tState++;
          }
          break;
      case 1:
          if (++tTimer > 11)
          {
              tTimer = 0;
              tState++;
          }
          break;
      case 2:
          if (GetLinkPlayerCount_2() >= GetSavedPlayerCount())
          {
              if (IsLinkMaster())
              {
                  if (++tTimer > 30)
                  {
                      CheckShouldAdvanceLinkState();
                      tState++;
                  }
              }
              else
              {
                  tState++;
              }
          }
          break;
      case 3:
          if (gReceivedRemoteLinkPlayers == TRUE && IsLinkPlayerDataExchangeComplete() == TRUE)
          {
              DestroyTask(taskId);
          }
          break;
      }
}

/** void TrySetBattleTowerLinkType(void) */
export function TrySetBattleTowerLinkType(): any {
  if (gWirelessCommType == 0)
          gLinkType = (0x2288);
}

